<?php if(!defined('ABSPATH'))exit;global $wpdb;$t=ICD_Visitas_Database::table('escolas');$tm=ICD_Visitas_Database::table('municipios');$rows=$wpdb->get_results("SELECT e.*,m.nome municipio FROM $t e LEFT JOIN $tm m ON m.id=e.municipio_id ORDER BY e.nome");$mun=$wpdb->get_results("SELECT * FROM $tm WHERE ativo=1 ORDER BY nome");$edit=isset($_GET['edit'])?$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d",absint($_GET['edit']))):null;?>
<div class="wrap icd-admin"><h1>Escolas</h1><form class="icd-form-grid" method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>"><?php wp_nonce_field('icd_save_escola');?><input type="hidden" name="action" value="icd_save_escola"><input type="hidden" name="id" value="<?php echo (int)($edit->id??0);?>"><label>Nome<input required name="nome" value="<?php echo esc_attr($edit->nome??'');?>"></label><label>Município<select name="municipio_id"><option value="0">Selecione</option><?php foreach($mun as $x)echo '<option value="'.$x->id.'" '.selected($edit->municipio_id??0,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Meta semanal<input type="number" step="0.5" min="0" name="meta_visitas_semana" value="<?php echo esc_attr($edit->meta_visitas_semana??'');?>"></label><label>Telefone<input name="telefone" value="<?php echo esc_attr($edit->telefone??'');?>"></label><label>E-mail<input type="email" name="email" value="<?php echo esc_attr($edit->email??'');?>"></label><label>Endereço<input name="endereco" value="<?php echo esc_attr($edit->endereco??'');?>"></label><label>Número<input name="numero" value="<?php echo esc_attr($edit->numero??'');?>"></label><label>Bairro<input name="bairro" value="<?php echo esc_attr($edit->bairro??'');?>"></label><label>CEP<input name="cep" value="<?php echo esc_attr($edit->cep??'');?>"></label><label class="full">Observações<textarea name="observacoes"><?php echo esc_textarea($edit->observacoes??'');?></textarea></label><?php if($edit):?><label class="icd-check full"><input type="checkbox" name="ativo" <?php checked($edit->ativo);?>> Escola ativa</label><?php endif;?><button class="button button-primary"><?php echo $edit?'Salvar alterações':'Adicionar escola';?></button></form><table class="widefat striped"><thead><tr><th>Escola</th><th>Município</th><th>Meta/semana</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html($r->nome);?></td><td><?php echo esc_html($r->municipio);?></td><td><?php echo esc_html($r->meta_visitas_semana??'—');?></td><td><a href="<?php echo esc_url(ICD_Visitas_Helpers::page_url('icd-visitas-escolas', ['edit' => (int) $r->id]));?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
